"""The field a pretty name describes, read as LaTeX: name -> defining polynomial.

This reads a name independently of the scripts that wrote it, so check_data.py can check
that each name gives the field of its label. Names are read as a mathematician would:

  * \\Q(g_1, ..., g_k) is generated by the g_j, and \\Q(\\zeta_{n})^+ is Q(\\zeta_n + \\zeta_n^{-1});
  * a g_j is built from integers, i, \\zeta_{n} and \\zeta_{n}^{k}, \\sqrt{...} and \\sqrt[n]{...}, sums,
    differences and products (juxtaposition, as in 2\\sqrt{3} or \\sqrt{2}\\sqrt{1 + \\sqrt{2}});
  * \\zeta_n is e^{2 pi i/n}, and \\sqrt[n]{z} is the principal root: the positive root of a
    positive number, the real root of a negative number for odd n (\\sqrt[3]{-2} = -\\sqrt[3]{2}),
    and e^{(log z)/n} otherwise (\\sqrt{-3} = i\\sqrt{3}).

The roots matter: \\sqrt{-2}\\sqrt{-3} is -\\sqrt{6}, not \\sqrt{6}, and Q(\\sqrt{A + B\\sqrt{-2} +
C\\sqrt{-3} + D\\sqrt{6}}) is a different field from the one with -D.

The field is built exactly, as a tower of PARI number fields: each root is adjoined by an
irreducible factor of x^n - z over the field so far, chosen by the numerical value of the
principal root, which fixes the embedding into C.
"""

import re

from pari_fields import pari

from cypari2.handle_error import PariError  # (after pari_fields, which checks cypari2 is there)

PRECISION = 256  # bits of the numerical values that pick the roots
_X = pari("x")
_Y = pari("y")


class NameError_(ValueError):
    """The name cannot be read."""


# ---------------------------------------------------------------- parsing

_TOKEN = re.compile(r"\\sqrt|\\zeta|\d+|[-+{}\[\]_^i]")


def parse_name(name):
    """The generators of a name, as expression trees, e.g. \\Q(\\sqrt{2}, i) ->
    [('root', 2, ('int', 2)), ('i',)]. \\Q gives []."""
    if name == r"\Q":
        return []
    m = re.match(r"^\\Q\(\\zeta_\{(\d+)\}\)\^\+$", name)
    if m:
        n = int(m[1])
        return [("add", [(1, ("zeta", n, 1)), (1, ("zeta", n, n - 1))])]
    m = re.match(r"^\\Q\((.*)\)$", name)
    if not m:
        raise NameError_(f"not of the form \\Q(...): {name}")
    return [_parse_expr(g) for g in _split_commas(m[1])]


def _split_commas(s):
    out, depth, start = [], 0, 0
    for k, c in enumerate(s):
        if c in "({[":
            depth += 1
        elif c in ")}]":
            depth -= 1
        elif c == "," and depth == 0:
            out.append(s[start:k])
            start = k + 1
    out.append(s[start:])
    return [g.strip() for g in out]


def _parse_expr(s):
    tokens = _TOKEN.findall(s)
    if "".join(tokens) != s.replace(" ", ""):
        raise NameError_(f"cannot read {s!r}")
    tree, k = _expr(tokens, 0)
    if k != len(tokens):
        raise NameError_(f"cannot read {s!r}")
    return tree


def _expect(tokens, k, t):
    if k >= len(tokens) or tokens[k] != t:
        raise NameError_(f"expected {t!r} in {''.join(tokens)!r}")
    return k + 1


def _int(tokens, k):
    if k >= len(tokens) or not tokens[k].isdigit():
        raise NameError_(f"expected a number in {''.join(tokens)!r}")
    return int(tokens[k]), k + 1


def _expr(tokens, k):
    terms = []
    sign = 1
    if k < len(tokens) and tokens[k] == "-":
        sign, k = -1, k + 1
    while True:
        t, k = _term(tokens, k)
        terms.append((sign, t))
        if k < len(tokens) and tokens[k] in "+-":
            sign, k = (1 if tokens[k] == "+" else -1), k + 1
        else:
            return ("add", terms), k


def _term(tokens, k):
    factors = []
    if k < len(tokens) and tokens[k].isdigit():
        c, k = _int(tokens, k)
        factors.append(("int", c))
    while k < len(tokens) and tokens[k] in (r"\sqrt", r"\zeta", "i"):
        f, k = _factor(tokens, k)
        factors.append(f)
    if not factors:
        raise NameError_(f"expected a term in {''.join(tokens)!r}")
    return ("mul", factors), k


def _factor(tokens, k):
    t = tokens[k]
    k += 1
    if t == "i":
        return ("i",), k
    if t == r"\zeta":
        k = _expect(tokens, k, "_")
        k = _expect(tokens, k, "{")
        n, k = _int(tokens, k)
        k = _expect(tokens, k, "}")
        e = 1
        if k < len(tokens) and tokens[k] == "^" and k + 1 < len(tokens) and tokens[k + 1] == "{":
            k = _expect(tokens, k + 1, "{")
            e, k = _int(tokens, k)
            k = _expect(tokens, k, "}")
        return ("zeta", n, e), k
    # \sqrt
    n = 2
    if k < len(tokens) and tokens[k] == "[":
        n, k = _int(tokens, k + 1)
        k = _expect(tokens, k, "]")
    k = _expect(tokens, k, "{")
    inner, k = _expr(tokens, k)
    k = _expect(tokens, k, "}")
    return ("root", n, inner), k


# ---------------------------------------------------------------- the tower of fields

class _Tower:
    """A number field F = Q(theta) with theta a root of T (in y), and a numerical value of
    theta fixing the embedding into C. Elements are polynomials in y modulo T, held in Elts
    so that they follow F when it grows."""

    def __init__(self):
        self.T = _Y
        self.theta = pari(0)
        self.elts = []
        self._zeta = {}

    def elt(self, poly):
        e = _Elt(self, pari(poly))
        self.elts.append(e)
        return e

    def value(self, e):
        return pari.subst(e.poly, _Y, self.theta)

    def adjoin(self, g, target):
        """An Elt alpha with g(alpha) = 0 and alpha (numerically) = target, where g is a
        polynomial in x over F (coefficients are polynomials in y)."""
        base = pari.poldegree(self.T, _Y) == 1
        fac = pari.factor(pari.subst(g, _Y, 0))[0] if base else pari.nffactor(self.T, g)[0]
        scored = []
        for h in fac:
            h = pari.lift(h)  # coefficients: polynomials in y (or rationals)
            hn = h if base else pari.subst(h, _Y, self.theta)
            d = int(pari.poldegree(h, _X))
            scale = sum(abs(c) for c in pari.Vec(hn)) * max(1, abs(target)) ** d
            scored.append((abs(pari.subst(hn, _X, target)) / scale, d, h))
        scored.sort(key=lambda t: t[0])
        self._check_small(scored[0][0], f"no factor of {g} vanishes at the root")
        if len(scored) > 1 and scored[1][0] < pari("1e-20"):
            raise NameError_(f"two factors of {g} vanish at the root")
        _, d, h = scored[0]
        h = h / pari.polcoef(h, d, _X)
        if d == 1:
            return self.elt(pari.lift(pari.Mod(-pari.polcoef(h, 0, _X), self.T)))
        self._extend(h, target)
        return self.elts[-1]

    def _extend(self, h, target):
        # F(alpha) = Q(theta'), theta' = alpha + k theta, and theta = a(theta')
        T2, a, k = pari.rnfequation(self.T, h, 1)
        theta2 = target + int(k) * self.theta
        a = pari.lift(a)  # in x
        # keep the polynomial small
        P, b = pari.polredbest(T2, 1)  # b(root of P) is a root of T2
        b = pari.lift(b)
        theta3 = self._root_near(P, theta2, pari.lift(pari.modreverse(pari.Mod(b, P))), T2)
        # old theta = a(theta'), theta' = b(theta'')
        old_in_new = pari.subst(a, _X, b)  # in x
        old_in_new = pari.subst(old_in_new, _X, _Y)
        for e in self.elts:
            e.poly = pari.lift(pari.Mod(pari.subst(e.poly, _Y, old_in_new), pari.subst(P, _X, _Y)))
        self.T = pari.subst(P, _X, _Y)
        self.theta = theta3
        alpha = pari.lift(pari.Mod(pari.subst(pari.subst(_X - int(k) * a, _X, b), _X, _Y), self.T))
        self.elts.append(_Elt(self, alpha))

    def _root_near(self, P, theta2, rev, T2):
        """The root of P (in x) that is the image of theta2 (a root of T2) under the map
        theta'' = rev(theta2), refined to full precision."""
        approx = pari.subst(rev, _X, theta2)
        roots = pari.polroots(P, precision=PRECISION)
        dists = sorted((abs(r - approx), k) for k, r in enumerate(roots))
        self._check_small(dists[0][0] / max(1, abs(approx)), "lost track of the embedding")
        if len(dists) > 1 and dists[1][0] < pari("1e-20"):
            raise NameError_("roots too close to tell apart")
        return roots[dists[0][1]]

    def _check_small(self, rel, msg):
        if rel > pari("1e-30"):
            raise NameError_(f"{msg} (error {float(rel):.2e}); try a higher PRECISION")

    def zeta(self, n):
        if n not in self._zeta:
            z = pari(f"exp(2 * Pi * I / {n})")
            self._zeta[n] = self.adjoin(pari.polcyclo(n, _X), z)
        return self._zeta[n]


class _Elt:
    def __init__(self, tower, poly):
        self.tower = tower
        self.poly = poly


def _principal_root(z, n):
    """The principal n-th root of the complex number z (the real root for odd n and real z)."""
    x, y = pari.real(z), pari.imag(z)
    if abs(y) < pari("1e-40") * max(1, abs(z)):
        if x >= 0:
            return pari.sqrtn(abs(x), n, precision=PRECISION)
        if n % 2:
            return -pari.sqrtn(abs(x), n, precision=PRECISION)
    return pari.exp(pari.log(z, precision=PRECISION) / n, precision=PRECISION)


def _eval(tree, F):
    """The Elt of tree in the tower F (which may grow)."""
    kind = tree[0]
    if kind == "int":
        return F.elt(tree[1])
    if kind == "i":
        return F.adjoin(_X ** 2 + 1, pari("I"))  # exact
    if kind == "zeta":
        _, n, e = tree
        z = F.zeta(n)
        return F.elt(pari.lift(pari.Mod(z.poly, F.T) ** e))
    if kind == "root":
        _, n, inner = tree
        b = _eval(inner, F)
        target = _principal_root(F.value(b), n)
        return F.adjoin(_X ** n - b.poly, target)
    if kind == "mul":
        es = [_eval(t, F) for t in tree[1]]
        p = pari.Mod(1, F.T)
        for e in es:
            p = p * e.poly
        return F.elt(pari.lift(p))
    if kind == "add":
        es = [(s, _eval(t, F)) for s, t in tree[1]]
        p = pari.Mod(0, F.T)
        for s, e in es:
            p = p + s * e.poly
        return F.elt(pari.lift(p))
    raise NameError_(f"unknown node {kind}")


def name_poly(name):
    """A polynomial (in x, monic, integral) of the field the name describes."""
    gens = parse_name(name)
    if not gens:
        return _X
    with_precision = pari.default("realprecision")
    pari.set_real_precision(int(PRECISION / 3.3) + 10)  # for pari("...") strings
    try:
        F = _Tower()
        es = [_eval(g, F) for g in gens]
        T = pari.subst(F.T, _Y, _X)
        polys = [pari.lift(pari.Mod(pari.subst(e.poly, _Y, _X), T)) for e in es]
        return _primitive_poly(T, polys)
    except PariError as err:
        raise NameError_(f"PARI could not build {name}: {err}")
    finally:
        pari.set_real_precision(int(with_precision))


def _primitive_poly(T, gens):
    """The minimal polynomial of a primitive element of the subfield of Q[x]/T generated by
    gens (polynomials in x)."""
    if len(gens) == 1:
        g = pari.minpoly(pari.Mod(gens[0], T))
        return _integral(g)
    for c in range(1, 50):
        prim = sum((c ** j) * g for j, g in enumerate(gens))
        g = pari.minpoly(pari.Mod(prim, T))
        if _generates(T, prim, int(pari.poldegree(g)), gens):
            return _integral(g)
    raise NameError_("no primitive element found")


def _generates(T, prim, d, gens):
    """Whether every generator is a polynomial in prim (degree d) in Q[x]/T."""
    n = int(pari.poldegree(T))
    powers = [pari.lift(pari.Mod(prim, T) ** j) for j in range(d)]
    M = pari.matrix(n, d, [pari.polcoef(p, i) for i in range(n) for p in powers])
    for g in gens:
        v = pari.Col([pari.polcoef(g, i) for i in range(n)])
        if len(pari.matinverseimage(M, v)) == 0:
            return False
    return True


def _integral(g):
    """A monic integral polynomial with the same root field as g (monic, rational)."""
    d = pari.denominator(pari.content(g))
    if d == 1:
        return g
    n = int(pari.poldegree(g))
    return d ** n * pari.subst(g, _X, _X / d)  # root d * alpha


# ---------------------------------------------------------------- checking a label

def check_name(label, name, lmfdb_coeffs=None):
    """Why the name does not describe the field with this label, or None if it does.

    Without lmfdb_coeffs, checks that the field of the name has the degree, signature and
    |discriminant| of the label n.r.D.i (not i: fields with the same n, r, D are not told
    apart). With lmfdb_coeffs (the LMFDB polynomial of the label, constant term first), checks
    that the two fields are isomorphic.
    """
    n, r, D, _ = (int(x) for x in label.split("."))
    try:
        P = name_poly(name)
    except NameError_ as e:
        return f"cannot read the name: {e}"
    if pari.poldegree(P) != n:
        return f"the name gives a field of degree {pari.poldegree(P)}"
    if n > 1:
        r1 = int(pari.polsturm(P))
        if r1 != r:
            return f"the name gives a field with {r1} real places, not {r}"
        # The basis is maximal at the primes dividing D, so this is the discriminant whenever
        # the field is unramified outside them; otherwise it has another prime factor.
        primes = [int(p) for p in pari.factor(D)[0]] if D > 1 else []
        disc = abs(int(pari.nfdisc([P, primes]))) if primes else abs(int(pari.nfdisc(P)))
        if disc != D:
            return f"the name gives a field of |disc| {disc}, not {D}"
    if lmfdb_coeffs is not None and n > 1:
        if not _isomorphic(P, pari.Polrev(list(lmfdb_coeffs)), primes):
            return "the name gives a field of the same degree, signature and |disc|, " \
                   "but not isomorphic to the LMFDB field"
    return None


def _isomorphic(P, Q, primes):
    try:
        if pari.polredabs([P, primes]) == pari.polredabs([Q, primes]):
            return True
    except PariError:  # polredabs can run out of stack in large degree
        pass
    nfP = pari.nfinit([P, primes]) if primes else pari.nfinit(P)
    return pari.nfisisom(nfP, Q).type() != "t_INT"
